import type { PolymorphicRef } from "@types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";

import { useMenu } from "../hooks/use-menu";
import { MenuClasses } from "../menu.styles";

const MenuTrigger = forwardRef<
  PolymorphicRef,
  React.ComponentPropsWithoutRef<"button"> & React.ComponentPropsWithoutRef<"div">
>(({ children, className, ...props }, ref) => {
  const { RadixComponent } = useMenu();
  const disabled =
    React.isValidElement(children) && (children.props as { disabled: boolean }).disabled;

  return (
    <RadixComponent.Trigger
      ref={ref}
      asChild
      className={clsx(MenuClasses.trigger, className)}
      disabled={disabled}
      {...props}
    >
      {children}
    </RadixComponent.Trigger>
  );
});
MenuTrigger.displayName = "Menu.Trigger";

export { MenuTrigger };
